def unique(values,key):
    # Return a new list with values deduplicated by key, preserving the
    # first value for each hashable key and retaining input order.
    # Unhashable values are handled naturally since the dict lookup is
    # performed against the key, which is hashable when values are.
    result = []
    seen = {}
    for value in values:
        key = value[key]
        if key not in seen:
            result.append(value)
            seen[key] = value
    return result

